CREATE TABLE t(id INTEGER PRIMARY KEY, g, i, r);
INSERT INTO t VALUES(0,'c',-1,1.0000000000000002),(1,'a',4294967296,0.0),(2,'c',NULL,1.7976931348623157e308),(3,'c',123456789012,2.5),(4,'b',2147483647,0.0),(5,'a',65535,1e-10),(6,'b',10,1e10),(7,'a',2,1.7976931348623157e308),(8,'c',7,4.35),(9,'b',4294967296,100.0),(10,'b',4294967296,1.7976931348623157e308),(11,'a',-7,9.99999999999999e22),(12,'b',255,1.5),(13,'c',-1,-0.000123),(14,'a',-9223372036854775807,123456.789),(15,NULL,256,0.1),(16,'a',-2147483648,1.7976931348623157e308),(17,'b',9223372036854775807,1.0000000000000002),(18,NULL,65535,0.0),(19,'c',123456789012,4.35),(20,'a',65535,1.7976931348623157e308),(21,'b',-7,5e-324);
SELECT g, count(*), count(i), sum(i), total(i), avg(i), min(i), max(i), sum(r), avg(r), group_concat(i) FROM t GROUP BY g ORDER BY g;
SELECT g, i, r, row_number() OVER (PARTITION BY g ORDER BY i, id), sum(r) OVER (ORDER BY id ROWS 3 PRECEDING), rank() OVER (ORDER BY i), lag(i) OVER (ORDER BY id), ntile(3) OVER (ORDER BY id) FROM t ORDER BY id;
SELECT * FROM t WHERE i > 5 OR r < 1.0 ORDER BY r, i, id LIMIT 20;
SELECT i, r, i + r, i * r, i / (r + 1) FROM t ORDER BY id;
